package com.bankresizer;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;

/**
 * How much room the bank window has to grow, and which ancestors must grow with
 * it. The bank sits in a fixed slot inside the play area, not on the canvas, so
 * the chain above it decides both the bound and what would clip a wider window.
 */
final class BankRoom
{
	/** Ancestors with an absolute width, which have to be widened by hand. */
	private final List<Widget> slots;

	/** Window and ancestors in play, innermost first. Resize in reverse, so a
	 * parent is sized before its children recompute from it. */
	private final List<Widget> chain;

	/**
	 * The play area: the first ancestor above the slots, which keeps its own size.
	 * Measured live at 725x550 on a 940x715 canvas, the canvas less the side panel
	 * and chatbox. Bounding by it keeps a wider bank off both.
	 */
	private final Widget viewport;

	/** Widest the bank window may become before an ancestor would clip it. */
	private final int limit;

	/** Whether the bank sits in a box another plugin keeps to its own size. */
	private final boolean boxed;

	private BankRoom(List<Widget> slots, List<Widget> chain, Widget viewport, int limit,
		boolean boxed)
	{
		this.slots = slots;
		this.chain = chain;
		this.viewport = viewport;
		this.limit = limit;
		this.boxed = boxed;
	}

	@Nullable
	Widget getViewport()
	{
		return viewport;
	}

	/** Tallest the bank window may become, or 0 if the play area is unknown. */
	int getHeightLimit()
	{
		return viewport == null ? 0 : viewport.getHeight();
	}

	List<Widget> getSlots()
	{
		return slots;
	}

	List<Widget> getChain()
	{
		return chain;
	}

	/**
	 * Whether the bank is inside something that fills the height of the client
	 * but not its width. The game never builds it that way, so it means a
	 * plugin has restyled the interface and is placing the bank itself.
	 */
	boolean isBoxed()
	{
		return boxed;
	}

	int getLimit()
	{
		return limit;
	}

	/** Measures the chain from {@code window} up to the root of the tree. */
	static BankRoom measure(Widget window, int canvasWidth, int canvasHeight)
	{
		if (window == null || canvasWidth <= 0)
		{
			return new BankRoom(Collections.emptyList(), Collections.emptyList(), null, 0,
				false);
		}

		List<Widget> chain = new ArrayList<>();
		for (Widget node = window; node != null && chain.size() < MAX_DEPTH; node = node.getParent())
		{
			chain.add(node);
		}

		int[] widths = new int[chain.size()];
		int[] heights = new int[chain.size()];
		int[] modes = new int[chain.size()];
		for (int i = 0; i < chain.size(); i++)
		{
			widths[i] = chain.get(i).getWidth();
			heights[i] = chain.get(i).getHeight();
			modes[i] = chain.get(i).getWidthMode();
		}

		BankChainPlan plan = BankChainPlan.of(widths, heights, modes, canvasWidth,
			canvasHeight);		int highestSlot = plan.getHighestSlot();

		List<Widget> slots = new ArrayList<>();
		for (int i = 0; i <= highestSlot; i++)
		{
			if (modes[i] == WidgetSizeMode.ABSOLUTE)
			{
				slots.add(chain.get(i));
			}
		}

		Widget viewport = plan.getViewport() < 0 ? null : chain.get(plan.getViewport());
		int limit = viewport == null ? window.getWidth() : viewport.getWidth();

		// Stop at the topmost slot. Anything above it is a tracking ancestor that
		// must keep its own size: that one is the limit, not something to widen.
		return new BankRoom(slots, chain.subList(0, highestSlot + 1), viewport, limit,
			plan.isBoxed());
	}

	/** Guards against a malformed tree sending the walk into a long loop. */
	private static final int MAX_DEPTH = 16;
}

package com.bankresizer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertTrue;
import net.runelite.api.widgets.WidgetSizeMode;
import org.junit.Test;

/** Pins the ancestor rule to a chain measured on a live client. */
public class BankChainPlanTest
{
	private static final int ABS = WidgetSizeMode.ABSOLUTE;

	private static final int MINUS = WidgetSizeMode.MINUS;

	private static final int CANVAS = 940;

	/** Taller than any ancestor in these chains, so only width decides. */
	private static final int NO_HEIGHT = Integer.MAX_VALUE;

	/** The real chain: window, tracking root, fixed slot, play area, canvas. */
	private static BankChainPlan live()
	{
		return BankChainPlan.of(
			new int[]{488, 512, 512, 725, 940},
			new int[]{0, 0, 0, 0, 0},
			new int[]{ABS, MINUS, ABS, MINUS, ABS},
			CANVAS, NO_HEIGHT);
	}

	@Test
	public void stopsAtTheFullCanvasRoot()
	{
		// Widening the canvas-wide ancestor would push the bank out over the side
		// panel, so it is not in play.
		assertEquals(4, live().getEnd());
	}

	@Test
	public void findsTheFixedSlotThatWasClipping()
	{
		// Index 2 is the 512 wide slot. Leaving it behind is what clipped the
		// widened window and made the bank look like it had shifted left.
		assertEquals(2, live().getHighestSlot());
	}

	@Test
	public void picksThePlayAreaAsTheLimit()
	{
		// Index 3 at 725, the canvas less the side panel, not the 940 canvas.
		assertEquals(3, live().getViewport());
	}

	@Test
	public void theLimitIsAboveEveryWidenedSlot()
	{
		// Otherwise we would be bounded by something we are about to resize.
		BankChainPlan plan = live();
		assertTrue(plan.getViewport() > plan.getHighestSlot());
		assertTrue(plan.getViewport() < plan.getEnd());
	}

	@Test
	public void trackingAncestorsAreNeverTreatedAsSlots()
	{
		// A chain with no fixed ancestor needs nothing widened above the window.
		BankChainPlan plan = BankChainPlan.of(
			new int[]{488, 512, 725, 940},
			new int[]{0, 0, 0, 0},
			new int[]{MINUS, MINUS, MINUS, ABS},
			CANVAS, NO_HEIGHT);

		assertEquals(-1, plan.getHighestSlot());
	}

	@Test
	public void handlesAChainWithNothingAboveTheWindow()
	{
		BankChainPlan plan = BankChainPlan.of(
			new int[]{488},
			new int[]{0},
			new int[]{ABS},
			CANVAS, NO_HEIGHT);

		assertEquals(0, plan.getHighestSlot());
		assertEquals(-1, plan.getViewport());
	}

	@Test
	public void aWindowAlreadyFillingTheCanvasIsNotInPlay()
	{
		BankChainPlan plan = BankChainPlan.of(
			new int[]{940, 940},
			new int[]{0, 0},
			new int[]{ABS, ABS},
			CANVAS, NO_HEIGHT);

		assertEquals(0, plan.getEnd());
		assertEquals(-1, plan.getHighestSlot());
	}

	@Test
	public void picksTheNarrowestTrackingAncestorNotTheFirst()
	{
		// The tightest constraint wins, wherever it sits in the chain.
		BankChainPlan plan = BankChainPlan.of(
			new int[]{488, 512, 800, 700, 940},
			new int[]{0, 0, 0, 0, 0},
			new int[]{ABS, ABS, MINUS, MINUS, ABS},
			CANVAS, NO_HEIGHT);

		assertEquals(3, plan.getViewport());
	}

	@Test
	public void readsTheOrdinaryChain()
	{
		// Measured: bank window, its holder, the slot, the play area, the screen.
		BankChainPlan plan = BankChainPlan.of(
			new int[]{488, 512, 512, 691, 941},
			new int[]{330, 334, 334, 550, 715},
			new int[]{ABS, MINUS, ABS, MINUS, MINUS},
			941, 715);

		assertEquals(4, plan.getEnd());
		assertEquals(2, plan.getHighestSlot());
		assertEquals(3, plan.getViewport());
	}

	@Test
	public void readsAChainWithAFullHeightContainerAboveThePlayArea()
	{
		// Measured with a plugin that restyles the interface. The container above
		// the play area is no wider than it but as tall as the whole client, and
		// taking it for a slot left nothing to bound the bank, so the bank could
		// only ever be its own width and dropped back to eight columns.
		BankChainPlan plan = BankChainPlan.of(
			new int[]{488, 512, 512, 692, 692},
			new int[]{330, 334, 334, 550, 715},
			new int[]{ABS, MINUS, ABS, MINUS, ABS},
			941, 715);

		assertEquals(4, plan.getEnd());
		assertEquals(2, plan.getHighestSlot());
		assertEquals(3, plan.getViewport());
	}

	@Test
	public void knowsTheOrdinaryChainIsNotBoxed()
	{
		BankChainPlan plan = BankChainPlan.of(
			new int[]{488, 512, 512, 691, 941},
			new int[]{330, 334, 334, 550, 715},
			new int[]{ABS, MINUS, ABS, MINUS, MINUS},
			941, 715);

		assertFalse(plan.isBoxed());
	}

	@Test
	public void spotsABoxAsTallAsTheClientButNarrowerThanIt()
	{
		// Measured with a plugin that restyles the interface. It keeps the bank
		// window at its own width, so there is no point widening it.
		BankChainPlan plan = BankChainPlan.of(
			new int[]{488, 512, 512, 692, 692},
			new int[]{330, 334, 334, 550, 715},
			new int[]{ABS, MINUS, ABS, MINUS, ABS},
			941, 715);

		assertTrue(plan.isBoxed());
	}

	@Test
	public void toleratesMissingOrMismatchedInput()
	{
		assertEquals(0, BankChainPlan.of(null, null, null, CANVAS, NO_HEIGHT).getEnd());
		assertEquals(0, BankChainPlan.of(
			new int[]{1},
			new int[]{0},
			new int[]{ABS, ABS},
			CANVAS, NO_HEIGHT).getEnd());
		assertEquals(-1, BankChainPlan.of(new int[0], null, new int[0], CANVAS, NO_HEIGHT).getHighestSlot());
	}
}

package com.bankresizer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

/** Pins the ordering rule "view all items" exposed: child order is not screen order. */
public class BankGridTest
{

	private static int[] itemIdsOf(int n)
	{
		int[] ids = new int[n];
		java.util.Arrays.fill(ids, 995);
		return ids;
	}

	private static int[] heightsOf(int n)
	{
		int[] heights = new int[n];
		java.util.Arrays.fill(heights, BankLayout.ITEM_HEIGHT);
		return heights;
	}

	private static BankGrid.Cell cellFor(BankGrid.Plan plan, int index)
	{
		for (BankGrid.Cell cell : plan.getCells())
		{
			if (cell.getIndex() == index)
			{
				return cell;
			}
		}

		throw new AssertionError("no cell for child " + index);
	}

	@Test
	public void ordersByPositionRatherThanChildIndex()
	{
		// Child 0 is drawn below child 1, as happens on the view all tab.
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 51},
			new int[]{804, 0},
			new int[]{995, 995},
			new int[]{32, 32},
			8);

		// Both fit on row 0 at eight columns, so the order shows in the column:
		// the child drawn higher up is laid out first despite its later index.
		assertEquals(0, cellFor(plan, 1).getColumn());
		assertEquals(1, cellFor(plan, 0).getColumn());
	}

	@Test
	public void readsLeftToRightWithinARow()
	{
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{99, 51},
			new int[]{0, 0},
			new int[]{995, 995},
			new int[]{32, 32},
			8);

		assertEquals(0, cellFor(plan, 1).getColumn());
		assertEquals(1, cellFor(plan, 0).getColumn());
	}

	@Test
	public void wrapsAtTheColumnCount()
	{
		int[] xs = new int[10];
		int[] ys = new int[10];
		for (int i = 0; i < 10; i++)
		{
			xs[i] = i * 48;
		}

		BankGrid.Plan plan = BankGrid.plan(xs, ys, itemIdsOf(10), heightsOf(10), 8);

		assertEquals(0, cellFor(plan, 7).getY());
		assertEquals(BankLayout.ROW_PITCH, cellFor(plan, 8).getY());
		assertEquals(0, cellFor(plan, 8).getColumn());
		assertEquals(2 * BankLayout.ROW_PITCH, plan.getHeight());
	}

	@Test
	public void separatorHeldAtTheEndOfTheArrayLandsBetweenItsGroups()
	{
		// The live shape: items at 0 and 1, the separator last, and its y says it
		// belongs between them rather than after both.
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 51, 51},
			new int[]{0, 804, 797},
			new int[]{995, 995, -1},
			new int[]{32, 32, 2},
			8);

		assertEquals(0, cellFor(plan, 0).getY());
		assertTrue(cellFor(plan, 2).getY() > 0);
		assertTrue(cellFor(plan, 1).getY() > cellFor(plan, 2).getY());
		assertTrue(cellFor(plan, 2).getKind() == BankGrid.Kind.RULE);
	}

	@Test
	public void separatorClosesAPartFilledRow()
	{
		// Three items then a separator, at eight columns: the separator must not
		// share the row the items were still filling.
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 99, 147, 51},
			new int[]{0, 0, 0, 10},
			new int[]{995, 995, 995, -1},
			new int[]{32, 32, 32, 2},
			8);

		assertEquals(0, cellFor(plan, 2).getY());
		assertTrue(cellFor(plan, 3).getY() >= BankLayout.ROW_PITCH);
	}

	@Test
	public void separatorBelowEverythingStaysAtTheBottom()
	{
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 51},
			new int[]{0, 900},
			new int[]{995, -1},
			new int[]{32, 2},
			8);

		assertEquals(0, cellFor(plan, 0).getY());
		assertEquals(BankLayout.ROW_PITCH, cellFor(plan, 1).getY());
		assertEquals(2 * BankLayout.ROW_PITCH, plan.getHeight());
	}

	@Test
	public void everyChildIsPlacedExactlyOnce()
	{
		int[] xs = {51, 99, 147, 51, 51};
		int[] ys = {0, 0, 0, 100, 50};
		int[] ws = {36, 36, 36, 36, 374};
		int[] hs = {32, 32, 32, 32, 2};

		List<BankGrid.Cell> cells = BankGrid.plan(xs, ys, ws, hs, 8).getCells();

		assertEquals(5, cells.size());
		for (int i = 0; i < 5; i++)
		{
			cellFor(BankGrid.plan(xs, ys, ws, hs, 8), i);
		}
	}

	@Test
	public void widerGridUsesFewerRows()
	{
		int[] xs = new int[20];
		int[] ys = new int[20];
		for (int i = 0; i < 20; i++)
		{
			xs[i] = (i % 8) * 48;
			ys[i] = (i / 8) * 36;
		}

		assertTrue(BankGrid.plan(xs, ys, itemIdsOf(20), heightsOf(20), 12).getHeight()
			< BankGrid.plan(xs, ys, itemIdsOf(20), heightsOf(20), 8).getHeight());
	}

	@Test
	public void reproducesTheGamesOwnGapAtAGroupBoundary()
	{
		// The live shape. One row of a group ends at y=756, the rule sits at 797
		// and the next group starts at 804, so the boundary costs one row step plus
		// 12px of slack, not a whole extra row.
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 51, 51},
			new int[]{756, 804, 797},
			new int[]{995, 995, -1},
			new int[]{32, 32, 2},
			8);

		int firstRow = cellFor(plan, 0).getY();
		int nextGroup = cellFor(plan, 1).getY();

		assertEquals(0, firstRow);
		assertEquals(BankLayout.ROW_PITCH + 12, nextGroup);
		assertEquals(nextGroup - 7, cellFor(plan, 2).getY());
	}

	@Test
	public void furnitureKeepsItsOffsetAboveTheGroupItIntroduces()
	{
		// A rule and a heading drawn at different heights above the same group keep
		// their spacing relative to it rather than each being given a row.
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 51, 51, 51},
			new int[]{756, 804, 797, 799},
			new int[]{995, 995, -1, -1},
			new int[]{32, 32, 2, 2},
			8);

		int nextGroup = cellFor(plan, 1).getY();

		assertEquals(nextGroup - 7, cellFor(plan, 2).getY());
		assertEquals(nextGroup - 5, cellFor(plan, 3).getY());
	}

	@Test
	public void noBoundaryAddsNoSlack()
	{
		// Two plain rows a row pitch apart stay a row pitch apart.
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 51},
			new int[]{0, BankLayout.ROW_PITCH},
			new int[]{995, 995},
			new int[]{32, 32},
			1);

		assertEquals(0, cellFor(plan, 0).getY());
		assertEquals(BankLayout.ROW_PITCH, cellFor(plan, 1).getY());
	}

	@Test
	public void fillerCoversTheCellsSpareAtTheEndOfItsRow()
	{
		// Three items then a filler, at eight columns: it covers the five cells
		// left over, starting at column three, not a row of its own at the left.
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 99, 147, 195},
			new int[]{0, 0, 0, 4},
			new int[]{995, 995, 995, -1},
			new int[]{32, 32, 32, 32},
			8);

		BankGrid.Cell filler = cellFor(plan, 3);

		assertEquals(BankGrid.Kind.FILLER, filler.getKind());
		assertEquals(3, filler.getColumn());
		assertEquals(5, filler.getSpan());
		assertEquals(0, filler.getY());
	}

	@Test
	public void fillerCollapsesWhenTheRowCameOutFull()
	{
		// At three columns those same three items fill the row exactly, so there
		// is nothing left to cover and the block has to disappear.
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 99, 147, 195},
			new int[]{0, 0, 0, 4},
			new int[]{995, 995, 995, -1},
			new int[]{32, 32, 32, 32},
			3);

		assertEquals(0, cellFor(plan, 3).getSpan());
	}

	@Test
	public void itemIdTellsAnItemFromAFiller()
	{
		assertEquals(BankGrid.Kind.ITEM, BankGrid.kindOf(995, 32));
		assertEquals(BankGrid.Kind.FILLER, BankGrid.kindOf(BankGrid.NO_ITEM, 32));
		assertEquals(BankGrid.Kind.RULE, BankGrid.kindOf(BankGrid.NO_ITEM, 2));

		// A filler covering one cell is resized to exactly an item's width, so a
		// width test would promote it to an item on the next pass.
		assertEquals(BankGrid.Kind.FILLER, BankGrid.kindOf(BankGrid.NO_ITEM, 32));
	}

	@Test
	public void toleratesEmptyAndMismatchedInput()
	{
		assertEquals(0, BankGrid.plan(new int[0], new int[0], new int[0], new int[0], 8).getHeight());
		assertEquals(0, BankGrid.plan(null, null, null, null, 8).getHeight());
		assertEquals(0, BankGrid.plan(new int[]{1}, new int[]{1, 2}, new int[]{995},
			new int[]{32}, 8).getHeight());
	}

	@Test
	public void aZeroColumnGridDoesNotHang()
	{
		BankGrid.Plan plan = BankGrid.plan(
			new int[]{51, 99},
			new int[]{0, 0},
			new int[]{995, 995},
			new int[]{32, 32},
			0);

		assertEquals(2 * BankLayout.ROW_PITCH, plan.getHeight());
	}
}

package com.bankresizer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Pins the layout maths to [proc,bankmain_build]; these fail first if it changes. */
public class BankLayoutTest
{
	@Test
	public void vanillaWidthYieldsVanillaPadding()
	{
		// The script derives padding as (width - 51 - 35 - 8 * 36) / 7, which at
		// the stock width of 460 works out to the documented 12px gap.
		int padding = BankLayout.paddingFor(
			BankLayout.VANILLA_CONTAINER_WIDTH, BankLayout.VANILLA_COLUMNS);

		assertEquals(BankLayout.VANILLA_PADDING, padding);
	}

	@Test
	public void vanillaColumnsNeedVanillaWidth()
	{
		assertEquals(BankLayout.VANILLA_CONTAINER_WIDTH,
			BankLayout.containerWidthFor(BankLayout.VANILLA_COLUMNS));
	}

	@Test
	public void widerGridKeepsVanillaPadding()
	{
		// Adding columns must not change the gap between items, otherwise the
		// grid would visibly re-space itself as the count changes.
		for (int columns = 8; columns <= 24; columns++)
		{
			int width = BankLayout.containerWidthFor(columns);
			assertEquals("columns=" + columns,
				BankLayout.VANILLA_PADDING, BankLayout.paddingFor(width, columns));
		}
	}

	@Test
	public void eachColumnCostsOnePitch()
	{
		assertEquals(BankLayout.COLUMN_PITCH,
			BankLayout.containerWidthFor(11) - BankLayout.containerWidthFor(10));
	}

	@Test
	public void maxColumnsNeverDropsBelowVanilla()
	{
		// A cramped or fixed-mode client must fall back to stock behaviour rather
		// than compute a narrower, broken grid.
		assertEquals(BankLayout.VANILLA_COLUMNS, BankLayout.maxColumnsFor(0));
		assertEquals(BankLayout.VANILLA_COLUMNS, BankLayout.maxColumnsFor(100));
		assertEquals(BankLayout.VANILLA_COLUMNS,
			BankLayout.maxColumnsFor(BankLayout.VANILLA_CONTAINER_WIDTH));
	}

	@Test
	public void neverAsksForMoreColumnsThanTheClientWillDraw()
	{
		// At 29 the game stops rebuilding the bank and nothing is drawn, however
		// much room there is: seen on play areas of both 725 and 2952.
		assertEquals(BankLayout.MAX_COLUMNS, BankLayout.maxColumnsFor(100000));
		assertEquals(BankLayout.MAX_COLUMNS,
			BankLayout.maxColumnsFor(BankLayout.containerWidthFor(40)));
	}

	@Test
	public void maxColumnsRoundTripsWithRequiredWidth()
	{
		for (int columns = 8; columns <= BankLayout.MAX_COLUMNS; columns++)
		{
			int width = BankLayout.containerWidthFor(columns);
			assertEquals("columns=" + columns, columns, BankLayout.maxColumnsFor(width));

			// One pixel short of the requirement must not allow the extra column.
			assertEquals("columns=" + columns,
				columns - 1 < 8 ? 8 : columns - 1, BankLayout.maxColumnsFor(width - 1));
		}
	}

	@Test
	public void firstItemSitsAtScriptOrigin()
	{
		assertEquals(BankLayout.START_X, BankLayout.itemX(0, BankLayout.VANILLA_PADDING));
		assertEquals(0, BankLayout.itemY(0));
	}

	@Test
	public void itemPositionsMatchScriptFormula()
	{
		// x = 51 + column * (36 + padding), y = row * 36
		int padding = BankLayout.VANILLA_PADDING;
		assertEquals(51 + 3 * (36 + padding), BankLayout.itemX(3, padding));
		assertEquals(5 * BankLayout.ROW_PITCH, BankLayout.itemY(5));
	}

	@Test
	public void lastVanillaColumnStaysInsideContainer()
	{
		int padding = BankLayout.VANILLA_PADDING;
		int rightEdge = BankLayout.itemX(BankLayout.VANILLA_COLUMNS - 1, padding)
			+ BankLayout.ITEM_WIDTH;

		assertTrue("last column overflows: " + rightEdge,
			rightEdge <= BankLayout.VANILLA_CONTAINER_WIDTH - BankLayout.RIGHT_INSET);
	}

	@Test
	public void rowsForCountsPartialRows()
	{
		assertEquals(0, BankLayout.rowsFor(0, 10));
		assertEquals(1, BankLayout.rowsFor(1, 10));
		assertEquals(1, BankLayout.rowsFor(10, 10));
		assertEquals(2, BankLayout.rowsFor(11, 10));
	}

	@Test
	public void moreColumnsNeverNeedsMoreRows()
	{
		for (int items = 0; items <= 200; items++)
		{
			assertTrue("items=" + items,
				BankLayout.rowsFor(items, 12) <= BankLayout.rowsFor(items, 8));
		}
	}

	@Test
	public void emptyGridHasNoScroll()
	{
		assertEquals(0, BankLayout.scrollHeightFor(0));
	}

	@Test
	public void scrollHeightAddsScriptSlack()
	{
		assertEquals(4 * BankLayout.ROW_PITCH + BankLayout.SCROLL_PADDING,
			BankLayout.scrollHeightFor(4));
	}

	@Test
	public void singleColumnDoesNotDivideByZero()
	{
		assertEquals(BankLayout.VANILLA_PADDING, BankLayout.paddingFor(460, 1));
		assertEquals(BankLayout.VANILLA_PADDING, BankLayout.paddingFor(460, 0));
	}
}

